#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Apply's one-time setup on this Mac. Every stage checks first and skips
# what is already done, so it's safe to run again: ./scripts/setup-wizard.sh
APPLY_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# The data folder: the applicant's own files (src/apply/home.py).
APPLY_DATA="${APPLY_HOME:-$HOME/.config/apply}"
# The Worker profiles, as apply.browsers finds them.
export APPLY_PROFILES="${APPLY_PROFILES:-$APPLY_DATA/profiles}"
POLICIES="$APPLY_DATA/policies.yaml"
# The Records repo: $APPLY_RECORDS_REPO (owner/name), else apply-records under your own GitHub account (stage 2).
RECORDS="${APPLY_RECORDS_REPO:-}"

apply_cli() { (cd "$APPLY_DIR" && uv run apply "$@"); }
in_apply() { (cd "$APPLY_DIR" && "$@"); }
already() { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
keychain_has() { [[ -n "$(security find-generic-password -s "$1" -a "$2" -w 2>/dev/null || true)" ]]; }
policy_on() { grep -qE "^$1: true$" "$POLICIES"; }
# A Chrome has this profile open (a run, a rehearsal, or a sign-in window).
profile_open() { pgrep -f "user-data-dir=$1( |$)" >/dev/null 2>&1; }
# close_profile DIR quits the Chrome that has DIR open, as Cmd-Q would, so it saves its sign-in.
close_profile() {
  pkill -TERM -f "MacOS/Google Chrome --user-data-dir=$1( |$)" 2>/dev/null || true
  for _ in $(seq 1 20); do profile_open "$1" || return 0; sleep 1; done
  return 1
}
workers_busy() { pgrep -f "user-data-dir=$APPLY_PROFILES/worker-" >/dev/null 2>&1; }
# The Google account Chrome itself is signed in to in a profile, or nothing.
chrome_account() {
  in_apply uv run python -c "import sys; from pathlib import Path; from apply.browsers import google_account; print(google_account(Path(sys.argv[1])) or '')" "$1"
}
gmail_works() { in_apply env APPLY_TEST_GMAIL="$EMAIL" uv run pytest -q tests/test_gmail.py -k real >/dev/null 2>&1; }
banner_test() { in_apply env APPLY_TEST_NOTIFY=1 uv run pytest -q tests/test_notification.py -k real >/dev/null 2>&1; }

# turn_on KEY SUBJECT sets a switch to true in the data folder's policies.yaml (never a file in the repo).
turn_on() {
  sed -i '' "s/^$1: false$/$1: true/" "$POLICIES"
  printf '  %s✓ %s%s (%s)\n' "$GREEN" "$2" "$RESET" "$POLICIES"
}

run_wizard() {

TOTAL_STAGES=9

banner "Apply setup"

EMAIL=$(in_apply uv run python -c "from pathlib import Path; from apply.profile import ApplicantProfile; print(ApplicantProfile.load(Path('$APPLY_DATA/applicant-profile.yaml')).get('identity.email'))")

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Gmail app password"
say "Apply reads verification codes and links from $EMAIL over IMAP, read-only."
if keychain_has apply-gmail "$EMAIL" && gmail_works; then
  already "Keychain has an app password, and Gmail accepts it."
else
  keychain_has apply-gmail "$EMAIL" && warn "Keychain has an app password, but Gmail refused it: make a new one."
  open_url "https://myaccount.google.com/apppasswords"
  step "Sign in if Google asks. No app passwords page? Turn on 2-Step Verification first."
  step "Name it Apply, click Create, and copy the 16 letters Google shows."
  step "Paste them at the prompt below, without the spaces. It's hidden and asked twice."
  until security add-generic-password -U -s apply-gmail -a "$EMAIL" -w && gmail_works; do
    warn "Gmail didn't accept that one (or the two didn't match)."
    confirm "Try again?" || { SKIPPED+=("Gmail app password (docs/accounts-setup.md, step 1)"); break; }
  done
  gmail_works && already "Gmail signs in with the new app password."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Records repo"
gh auth status >/dev/null 2>&1 || gh auth login
RECORDS="${RECORDS:-$(gh api user -q .login)/apply-records}"
say "Each Application's Record (answers sent, a screenshot) goes to the private repo $RECORDS."
if gh repo view "$RECORDS" >/dev/null 2>&1; then
  already "$RECORDS exists."
elif confirm "Create $RECORDS as a private, empty repo?"; then
  gh repo create "$RECORDS" --private --description "Apply's Records: what each Application sent" >/dev/null
  already "Created $RECORDS."
else
  SKIPPED+=("the $RECORDS repo (docs/records-setup.md)")
fi
gh auth setup-git
if git ls-remote "https://github.com/$RECORDS.git" >/dev/null 2>&1; then
  already "git reaches it without asking for a password."
  if grep -qE '^records_remote: [^n]' "$POLICIES" 2>/dev/null; then
    already "policies.yaml sets records_remote."
  else
    printf 'records_remote: https://github.com/%s.git\n' "$RECORDS" >> "$POLICIES"
    already "Set records_remote in $POLICIES."
  fi
else
  warn "git can't reach it yet: see docs/records-setup.md, step 2."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Mac banner after each run"
say "After every run, a banner says what it did. Sending a test banner now."
banner_test || true
if ! confirm "Did a test banner show?"; then
  open_url "x-apple.systempreferences:com.apple.Notifications-Settings.extension"
  step "Find Script Editor, turn on Allow notifications, and choose Banners or Alerts."
  pause "Press Enter to send it again."
  banner_test || true
  confirm "Did it show this time?" || SKIPPED+=("Mac banners (docs/records-setup.md, step 3)")
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Phone pushes (ntfy)"
say "After every run, Apply pushes what waits on you to the ntfy app."
TOPIC=$(security find-generic-password -s apply-ntfy -a ntfy.sh -w 2>/dev/null || true)
if [[ -z "$TOPIC" ]]; then
  TOPIC="apply-$(openssl rand -hex 12)"
  security add-generic-password -U -s apply-ntfy -a ntfy.sh -w "$TOPIC"
  already "Made a private topic and saved it in Keychain."
fi
step "On your phone, install ntfy (App Store or Google Play) and open it."
step "Tap +, keep the server ntfy.sh, and subscribe to this topic:"
printf '\n      %s%s%s\n\n' "$BOLD" "$TOPIC" "$RESET"
note "Anyone who knows the topic can read the pushes, so keep it to yourself."
pause "Press Enter once you've subscribed, to send a test push."
apply_cli push-test >/dev/null || true
if confirm "Did a test push from Apply show on your phone?"; then
  if policy_on phone_push; then already "phone_push is on."; else turn_on phone_push "Turn on phone pushes"; fi
else
  SKIPPED+=("phone pushes: run apply push-test once subscribed")
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Worker profiles: Google sign-in"
say "Workers sign in with Google by picking your account, so their Chrome profiles need your sign-in."
note "Apply never types your Google password: you sign in here, by hand, once per profile."
note "Profiles: $APPLY_PROFILES"
while workers_busy; do
  warn "A run or rehearsal has the Worker profiles open."
  confirm "Wait for it to finish and check again?" || break
  pause "Press Enter once it has finished."
done
if workers_busy; then
  SKIPPED+=("Worker profile sign-in: run this wizard again when no run is going")
else
  for profile in "$APPLY_PROFILES"/worker-*; do
    name=$(basename "$profile")
    account=$(chrome_account "$profile")
    if [[ -n "$account" ]]; then already "$name is signed in as $account."; continue; fi
    confirm "Sign $name in now?" || { SKIPPED+=("$name: not signed in to Google (a run copies a signed-in profile over it)"); continue; }
    open -na "Google Chrome" --args --user-data-dir="$profile" --use-mock-keychain --password-store=basic \
      --no-first-run "https://accounts.google.com/"
    step "In the Chrome window that opened, sign in to Google as $EMAIL."
    step "When Chrome offers to sign in to Chrome itself, accept (sync can stay off)."
    step "If Chrome offers to save your password, choose Never."
    pause "Press Enter once you're signed in, and this wizard closes that Chrome."
    until close_profile "$profile"; do pause "That Chrome didn't close: quit it with Cmd-Q, then press Enter."; done
    account=$(chrome_account "$profile")
    if [[ -n "$account" ]]; then already "$name is signed in as $account."
    else warn "Chrome itself isn't signed in to $name. Re-run this stage to try again."; SKIPPED+=("$name: Chrome sign-in"); fi
  done
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Live runs"
if policy_on live_runs; then
  already "live_runs is on."
else
  say "While live_runs is off, apply run and approve-pass refuse to start. Rehearsals still work."
  say "Once on, a run submits for real, but the first 10 Applications (the Calibration run)"
  say "are held until you approve each one in the Apply window."
  if confirm "Turn live runs on now?"; then
    turn_on live_runs "Turn on live runs"
  else
    SKIPPED+=("live runs: set live_runs: true in $POLICIES")
  fi
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "First real submissions, watched"
if ! policy_on live_runs; then
  warn "Live runs are off, so this waits for them."
  SKIPPED+=("watched submissions: one watched submission each on Greenhouse, Lever and Ashby")
elif confirm "Submit one real Application each on Greenhouse, Lever and Ashby now, watching? (about 20 min)"; then
  say "This shows whether each job system's captcha lets a Worker through."
  step "Pick one posting on each that you actually want, and paste its link. Enter skips one."
  systems=(); links=()
  for system in Greenhouse Lever Ashby; do
    ask "LINK_$system" "$system posting link:" || true
    link_var="LINK_$system"
    if [[ -n "${!link_var:-}" ]]; then systems+=("$system"); links+=("${!link_var}"); fi
  done
  if (( ${#links[@]} )); then
    apply_cli add "${links[@]}"
    say "Apply fills them now. The Apply window shows each Worker live, and every one is held for you."
    apply_cli run --requests-only || warn "apply run stopped with an error: read its output above."
    step "In the Apply window's Needs you tab, check each held one: its Record shows what it will send."
    step "Press Approve on each one that's right."
    pause "Press Enter once they're approved, to submit them while you watch."
    apply_cli approve-pass || warn "approve-pass stopped with an error: read its output above."
    say "For each, what happened at submit?"
    body="Watched first submissions:"
    for i in "${!systems[@]}"; do
      ask "RESULT_${systems[$i]}" "${systems[$i]}: passed, challenged (could you solve it?) or blocked?" || true
      result_var="RESULT_${systems[$i]}"
      body+=$'\n'"- ${systems[$i]} (${links[$i]}): ${!result_var:-not recorded}"
    done
    printf '\n%s\n\n' "$body"
  else
    SKIPPED+=("watched submissions: no links given")
  fi
else
  SKIPPED+=("watched submissions: one watched submission each on Greenhouse, Lever and Ashby")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Daily schedule"
if ! policy_on live_runs; then
  warn "Live runs are off, so the schedule waits for them."
  SKIPPED+=("daily schedule: apply schedule install --load")
else
  say "launchd starts the Daily sweep each morning (schedule.daily_sweep_at in policies.yaml)"
  say "and checks for new Requests every 5 minutes."
  schedule=$(apply_cli schedule status 2>&1 || true)
  printf '%s\n' "$schedule" | sed 's/^/    /'
  if [[ $(grep -c ': loaded,' <<<"$schedule" || true) -ge 2 ]]; then
    already "Both jobs are loaded."
  elif confirm "Install and load both jobs?"; then
    apply_cli schedule install --load
  else
    SKIPPED+=("daily schedule: apply schedule install --load")
  fi
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Check everything"
apply_cli doctor || warn "A check failed: its line says how to fix it."
pause

finish
}

run_wizard "$@"; exit
